var standardRunTimePerPart = Number(global.get('standard_runtime_perpart'))||0.1;
var IOparts = global.get('goodparts');
var NIOparts = global.get('badparts');
var scrapCode = global.get('codes')||"";

// Calculate KPIs

// Availability = (Run Time) / (Shift Length - Breaks)
let availability = runTime/(runTime + downTime) || 0;

// Performance = (Standard Run Time Per Part × IOparts) / Run Time
let performance = ((standardRunTimePerPart * IOparts) / runTime) || 0;

// Quality = IOparts / (IOparts + NIOparts)
let quality = (IOparts / (IOparts + NIOparts)) || 0;

// OEE = Availability × Performance × Quality
let oee = (availability * performance * quality) || 0;

// Multiply by 100 to get the percentages
let oeePercentage = (oee * 100).toFixed(2);  // Assuming you want 2 decimal places
let availabilityPercentage = (availability * 100).toFixed(2);
let performancePercentage = (performance * 100).toFixed(2);
let qualityPercentage = (quality * 100).toFixed(2);

// Append '%' to the KPIs
oeePercentage += '%';
availabilityPercentage += '%';
performancePercentage += '%';
qualityPercentage += '%';

// Output the KPIs
msg.payload = {
    "OEE": oeePercentage,
    "Availability": availabilityPercentage,
    "Performance": performancePercentage,
    "Quality": qualityPercentage,
    "scrapCode": scrapCode
};

return msg;

