var x = msg.payload.toString(2);
var arr = [];

for (var temp of x)
{
    arr.push(Number(temp));
}
msg.payload = arr.reverse();
flow.set('siminputs_1',msg.payload)
return msg;

var simoutputs = flow.get('simoutputs_1')||[];
msg.payload = simoutputs.join("");
flow.set('simoutputs',parseInt(msg.payload, 2));
return msg;

//Inputs
var siminputs = flow.get('siminputs_1');
var sim_emstop = siminputs[1];
var sim_start = siminputs[2];
var sim_stop = siminputs[3];
var sim_sort_area_IR = siminputs[4];
var sim_sort_inductive = siminputs[5];
var sim_solenoid_sensor = siminputs[6];
var sim_assembly_chute_IR = siminputs[7];
var sim_assembly_area_through_beam= siminputs[8];
var sim_assembly_capacitive = siminputs[9];
var sim_assembly_inductive = siminputs[10];
var sim_reject_IR = siminputs[11];
var sim_reject_area_inductive = siminputs[12];


//Outputs
var simoutput = [];
for ( var i = 0; i<= 7 ; i++)
{
    simoutput.push(0);
}

var sim_chain_conveyor = 0;
var sim_sort_solenoid = 0;
var sim_reject_solenoid = 0;
var sim_rotary_solenoid = 0;
var sim_belt_conveyor = 0;
var sim_indication_start = 0;
var sim_indication_stop = 0;
var sim_reset_emstop = 0;

//-------------------Logic--------------------------

//Reset emergency stop
sim_reset_emstop = sim_stop;
if (sim_stop === 1)
{
    flow.set('sort_step',0);
    flow.set('count_step',0);
}

//Conveyor
sim_belt_conveyor = sim_chain_conveyor = sim_indication_start = sim_start;
sim_indication_stop = 0;

//Sort solenoid steps
var step = flow.get('sort_step')||0;
if (step === 0 && sim_sort_inductive === 1)
    {
        flow.set('sort_step',1);
    }

if (step === 0 && sim_sort_area_IR === 1 && sim_sort_inductive === 0)
    {
        sim_sort_solenoid = 1;
        flow.set('sort_step',1);
    }

if (step === 1 && sim_sort_area_IR === 0)
    {

        sim_sort_solenoid = 0;
        flow.set('sort_step',2);
    }

if (step === 2)
    {
        flow.set('sort_step',0);
    }


//Rotary solenoid
if (sim_sort_area_IR === 0)
    {
        sim_rotary_solenoid = 1
    }
else
    {
        sim_rotary_solenoid = 0
    }

//Counting objects
var count_step = flow.get('count_step')||0;
if (count_step === 0 && sim_assembly_inductive === 1)
    {
        flow.set('count_step',1);
    }

//good parts count
if (count_step === 1 && sim_assembly_capacitive === 0)
    {
        var goodparts = global.get('goodparts')||0;
        goodparts += 1;
        global.set('goodparts', goodparts)
        flow.set('count_step',2);
    }

//bad parts count
if (count_step == 1 && sim_assembly_inductive === 0)
    {
        var badparts = global.get('badparts')||0;
        badparts += 1;
        global.set('badparts', badparts)        
        flow.set('count_step',0);
    }

if (count_step === 2 && sim_assembly_capacitive === 1)
    {

        flow.set('count_step',3);
    }

if (count_step === 3 && sim_assembly_inductive === 0)
    {        
        flow.set('count_step',0);
    }

simoutput[0] = sim_chain_conveyor;
simoutput[1] = sim_sort_solenoid;
simoutput[2] = sim_reject_solenoid;
simoutput[3] = sim_rotary_solenoid;
simoutput[4] = sim_belt_conveyor;
simoutput[5] = sim_indication_start;
simoutput[6] = sim_indication_stop;
simoutput[7] = sim_reset_emstop;

var simoutput_reversed = simoutput.reverse();

//Convert array element to string
flow.set('simoutputs_1',simoutput_reversed.map(String))

var outputs = flow.get('simoutputs_1')||[];
var sim_belt_conveyor = outputs[3];

//Calculating runtime
if (sim_belt_conveyor === "1")
{
    var runtime = global.get('runtime')||0;
    runtime = runtime + 0.01166;
    global.set('runtime',runtime); 
}
if (sim_belt_conveyor === "0")
{
    var downtime = global.get('downtime')||.0;
    downtime = downtime + 0.0166;
    global.set('downtime',downtime); 
}
msg.payload = outputs;
return msg;
